  function workspaceDialog(title,description,body,className='subject-option-dialog'){const bg=document.createElement('div');bg.className='modal-bg confirm-bg';bg.style.display='flex';bg.innerHTML=`<div class="modal workspace-dialog ${className}" role="dialog" aria-modal="true"><header><div><h3>${esc(title)}</h3>${description?`<p>${esc(description)}</p>`:''}</div><button type="button" class="pf-head-btn subject-dialog-close" aria-label="Close" title="Close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg></button></header><div class="subject-dialog-body">${body}</div></div>`;document.body.appendChild(bg);const close=()=>bg.remove();bg.querySelector('.subject-dialog-close').onclick=close;bg.onclick=event=>{if(event.target===bg)close()};bg.onkeydown=event=>{if(event.key==='Escape')close()};return{bg,close,body:bg.querySelector('.subject-dialog-body')}}
  function choosePreviewSection(){const ids=sections(),options=ids.map(id=>`<button type="button" class="subject-dialog-option section-preview-option" data-section="${esc(id)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4V5Zm2 2v3h12V7H6Zm0 5v5h5v-5H6Zm7 0v5h5v-5h-5Z"/></svg><span><strong>${esc(id)}</strong><small>Preview this section's student view</small></span></button>`).join('');const {bg,close}=workspaceDialog('Preview, which section?','Choose the handled section whose student view you want to check.',`${options||'<p class="workspace-empty">No handled sections are available.</p>'}${previewMode?'<button type="button" class="subject-dialog-option exit-preview-option"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6-6 6 6 6 1.4-1.4L7.8 13H20v-2H7.8l3.6-3.6L10 6Z"/></svg><span><strong>Exit preview</strong><small>Return to faculty editing mode</small></span></button>':''}`,'preview-section-dialog');bg.querySelectorAll('[data-section]').forEach(button=>button.onclick=()=>{close();previewSection(button.dataset.section)});const exit=bg.querySelector('.exit-preview-option');if(exit)exit.onclick=()=>{close();previewMode=false;render()};bg.querySelector('[data-section]')?.focus()}
  function saveSubjectChanges(changes,message){const item=subjects.find(entry=>entry.code===subjectCode);if(!item)return;Object.assign(item,changes);DB.write('subjects',subjects);if(changes.workspaceColor){const card=[...document.querySelectorAll('#subjectList .sub-card')].find(entry=>entry.dataset.subjectCode===subjectCode);card?.style.setProperty('--course-accent',changes.workspaceColor);card?.style.setProperty('--course-soft',`color-mix(in srgb,${changes.workspaceColor} 12%,var(--surface))`)}log('edit','subject',subjectCode,{fields:Object.keys(changes)});notify(message,'success');render()}
  function openEditPrompt(){const options=[['color','M12 3a9 9 0 1 0 0 18h1.5a2 2 0 0 0 0-4H12a2 2 0 0 1 0-4h-.5A4.5 4.5 0 0 1 12 3Z','Edit color','Change the subject accent color'],['icon','M4 4h7v7H4V4Zm9 0h7v7h-7V4ZM4 13h7v7H4v-7Zm9 0h7v7h-7v-7Z','Edit icon','Choose the subject profile icon'],['rules','M5 4h14v3H5V4Zm0 6h14v3H5v-3Zm0 6h14v3H5v-3Z','Edit cells (exam rules)','Update rules used by this subject’s exams'],['description','M4 5h16v14H4V5Zm3 3v2h10V8H7Zm0 4v2h10v-2H7Zm0 4v1h7v-1H7Z','Hero profile description','Edit the text shown under the subject title']];const markup=options.map(([action,path,title,copy])=>`<button type="button" class="subject-dialog-option" data-edit-action="${action}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg><span><strong>${title}</strong><small>${copy}</small></span></button>`).join('');const dialog=workspaceDialog('Edit subject','Choose what you want to customize.',markup,'subject-edit-dialog');dialog.bg.querySelectorAll('[data-edit-action]').forEach(button=>button.onclick=()=>renderSubjectEditOption(dialog,button.dataset.editAction));dialog.bg.querySelector('[data-edit-action]')?.focus()}
  function renderSubjectEditOption(dialog,action){const s=course(),subjectExams=exams.filter(exam=>exam.subjectCode===subjectCode),back='<button type="button" class="subject-edit-back">&#8592; Edit options</button>';if(action==='color'){const colors=['#2f8d83','#3576a8','#7560ad','#b2762e','#b84b55','#4f7f45'];dialog.body.innerHTML=`${back}<h4>Edit color</h4><div class="subject-color-options">${colors.map(color=>`<button type="button" data-color="${color}" style="--swatch:${color}" aria-label="Use ${color}" title="${color}"></button>`).join('')}</div>`;dialog.body.querySelectorAll('[data-color]').forEach(button=>button.onclick=()=>{dialog.close();saveSubjectChanges({workspaceColor:button.dataset.color},'Subject color saved.')})}else if(action==='icon'){dialog.body.innerHTML=`${back}<h4>Edit icon</h4><div class="subject-icon-options">${Object.keys(iconPaths).map(name=>`<button type="button" data-icon="${name}" aria-label="Use ${name} icon">${iconSvg(name)}<span>${name}</span></button>`).join('')}</div>`;dialog.body.querySelectorAll('[data-icon]').forEach(button=>button.onclick=()=>{dialog.close();saveSubjectChanges({workspaceIcon:button.dataset.icon},'Subject icon saved.')})}else if(action==='rules'){const first=subjectExams[0]||{};dialog.body.innerHTML=`${back}<h4>Edit cells (exam rules)</h4><label class="dialog-input-label"><span>Passing percentage</span><input class="subject-rule-passing" type="number" min="0" max="100" value="${Number(first.passingPercent)||75}"></label><label class="dialog-input-label"><span>Allowed attempts</span><input class="subject-rule-attempts" type="number" min="1" value="${Number(first.maxAttempts)||1}"></label><label class="dialog-input-label"><span>Allowed materials</span><input class="subject-rule-materials" value="${esc(first.materials||'No additional materials')}"></label><button type="button" class="subject-edit-save">Save exam rules</button>`;dialog.body.querySelector('.subject-edit-save').onclick=()=>{const passing=Math.min(100,Math.max(0,Number(dialog.body.querySelector('.subject-rule-passing').value)||0)),attempts=Math.max(1,Number(dialog.body.querySelector('.subject-rule-attempts').value)||1),materials=dialog.body.querySelector('.subject-rule-materials').value.trim()||'No additional materials';subjectExams.forEach(exam=>Object.assign(exam,{passingPercent:passing,maxAttempts:attempts,materials}));DB.write('exams',exams);log('edit','subject-exam-rules',subjectCode,{passing,attempts,materials});dialog.close();notify('Subject exam rules saved.','success');render()}}else{dialog.body.innerHTML=`${back}<h4>Hero profile description</h4><label class="dialog-input-label"><span>Description</span><textarea class="subject-description-input" rows="5" placeholder="Describe this subject for students.">${esc(s.description||'')}</textarea></label><button type="button" class="subject-edit-save">Save description</button>`;dialog.body.querySelector('.subject-edit-save').onclick=()=>{const description=dialog.body.querySelector('.subject-description-input').value.trim();dialog.close();saveSubjectChanges({description},'Hero description saved.')}}dialog.body.querySelector('.subject-edit-back').onclick=()=>{dialog.close();openEditPrompt()}}
