  function addBlock(){const week=Math.max(1,Number(document.getElementById('workspaceWeek').value)||1),type=document.getElementById('workspaceBlockType').value,title=document.getElementById('workspaceBlockTitle').value.trim(),body=document.getElementById('workspaceBlockBody').value.trim(),url=document.getElementById('workspaceUrl').value.trim(),file=document.getElementById('workspaceFile').files?.[0],availability=document.getElementById('workspaceAvailability').value,openAt=document.getElementById('workspaceOpenAt').value,durationMinutes=Number(document.getElementById('workspaceDuration').value)||0,requiresPrevious=document.getElementById('workspacePrerequisite').checked,collapsible=document.getElementById('workspaceCollapsible').checked;if(type==='file'&&!file&&!editingBlockId){notify('Choose a file to attach.','error');return}if(type==='link'&&!/^https?:\/\//i.test(url)){notify('Enter a complete http:// or https:// link.','error');return}if(availability==='scheduled'&&!openAt){notify('Choose when this cell opens.','error');return}const save=dataUrl=>{const all=readContent(),existing=editingBlockId&&all.find(x=>x.id===editingBlockId),record=existing||{id:`block_${Date.now()}`,subjectCode,createdAt:new Date().toISOString()};Object.assign(record,{week,type,title:title||(file?.name||record.fileName||'Untitled'),body,url,fileName:file?.name||record.fileName||'',dataUrl:dataUrl||record.dataUrl||'',availability,openAt,durationMinutes,requiresPrevious,collapsible,updatedAt:new Date().toISOString(),updatedBy:facultyId});if(!existing)all.push(record);writeContent(all);log(existing?'edit':'add','subject-content',record.id,{subjectCode,week,title:record.title});notify(`Content cell ${existing?'saved':'added'}.`,'success');editingBlockId=null;editorOpen=false;render()};if(file){const reader=new FileReader();reader.onload=()=>save(reader.result);reader.onerror=()=>notify('The file could not be read.','error');reader.readAsDataURL(file)}else save('');}
