  function attachExamDialog(week){return new Promise(resolve=>{const available=exams.filter(exam=>exam.subjectCode===subjectCode);const bg=document.createElement('div');bg.className='modal-bg confirm-bg';bg.style.display='flex';bg.innerHTML=`<div class="modal attach-exam-dialog" role="dialog" aria-modal="true" aria-labelledby="attachExamTitle"><header><div><h3 id="attachExamTitle">Attach exam to Week ${week}</h3><p>Select an existing exam. It will also remain in the Examinations section.</p></div><button type="button" class="workspace-icon attach-exam-close" aria-label="Close">&#10005;</button></header><div class="attach-exam-list">${available.map(exam=>`<button type="button" data-exam-id="${esc(exam.id)}"><span><strong>${esc(exam.title||'Examination')}</strong><small>${esc(exam.date||'Always open')} · ${exam.questionIds?.length||questions.filter(question=>question.examId===exam.id).length} items</small></span><span aria-hidden="true">&#43;</span></button>`).join('')||'<p class="workspace-empty">Create an exam for this subject first.</p>'}</div></div>`;document.body.appendChild(bg);const done=value=>{bg.remove();resolve(value)};bg.querySelector('.attach-exam-close').onclick=()=>done(null);bg.onclick=event=>{if(event.target===bg)done(null)};bg.onkeydown=event=>{if(event.key==='Escape')done(null)};bg.querySelectorAll('[data-exam-id]').forEach(button=>button.onclick=()=>done(button.dataset.examId));bg.querySelector('[data-exam-id]')?.focus()})}
  function attachExamToWeek(week,examId){const exam=exams.find(item=>item.id===examId&&item.subjectCode===subjectCode);if(!exam){notify('That exam is not available for this subject.','error');return false}const all=readContent();if(all.some(item=>item.subjectCode===subjectCode&&item.week===week&&item.type==='exam'&&item.examId===examId)){notify('That exam is already attached to this week.','info');return false}const reference={id:`exam_block_${Date.now()}`,subjectCode,week,type:'exam',examId,title:exam.title||'Examination',availability:'open',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),updatedBy:facultyId};all.push(reference);writeContent(all);log('attach','subject-exam',examId,{subjectCode,week});notify(`Exam attached to Week ${week}.`,'success');render();return true}
